// Normalizes scraped raw financial product parameters and extracts evidence provenance
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  // Validates presence of core fields
  if (!data.product_name || !data.source_name) continue;

  results.push({
    json: {
      source_name: data.source_name,
      source_url: data.source_url || 'https://bank-offers.internal',
      product_name: data.product_name,
      product_type: 'Personal Loan',
      interest_rate_min: data.interest_rate_min || 10.50,
      interest_rate_max: data.interest_rate_max || 21.00,
      min_monthly_income: data.min_monthly_income || 25000.00,
      min_credit_score: data.min_credit_score || 700,
      min_age: data.min_age || 21,
      max_age: data.max_age || 60,
      eligible_employment_statuses: JSON.stringify(data.eligible_employment_statuses || ['Salaried']),
      eligibility_criteria_raw: data.eligibility_criteria_raw || 'Verified personal loan offering',
      eligibility_evidence: JSON.stringify(data.eligibility_evidence || { source: 'Portal published criteria' }),
      is_active: true
    }
  });
}

return results;
